import{_ as l,r as t,o as i,c as r,e as p,a as n,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"列表控制器 - October CMS - 3.x","titleTemplate":false,"description":"为任何后台页面添加列表管理功能。","frontmatter":{"subtitle":"为任何后台页面添加列表管理功能。"},"headers":[{"level":2,"title":"配置列表行为","slug":"配置列表行为","link":"#配置列表行为","children":[{"level":3,"title":"添加工具栏","slug":"添加工具栏","link":"#添加工具栏","children":[]},{"level":3,"title":"过滤列表","slug":"过滤列表","link":"#过滤列表","children":[]}]},{"level":2,"title":"定义列表列","slug":"定义列表列","link":"#定义列表列","children":[]},{"level":2,"title":"显示列表","slug":"显示列表","link":"#显示列表","children":[]},{"level":2,"title":"多个列表定义","slug":"多个列表定义","link":"#多个列表定义","children":[]},{"level":2,"title":"扩展列表行为","slug":"扩展列表行为","link":"#扩展列表行为","children":[{"level":3,"title":"扩展列表配置","slug":"扩展列表配置","link":"#扩展列表配置","children":[]},{"level":3,"title":"覆盖控制器操作","slug":"覆盖控制器操作","link":"#覆盖控制器操作","children":[]},{"level":3,"title":"覆盖视图","slug":"覆盖视图","link":"#覆盖视图","children":[]},{"level":3,"title":"扩展列定义","slug":"扩展列定义","link":"#扩展列定义","children":[]},{"level":3,"title":"注入 CSS 行类","slug":"注入-css-行类","link":"#注入-css-行类","children":[]},{"level":3,"title":"覆盖列 URL","slug":"覆盖列-url","link":"#覆盖列-url","children":[]},{"level":3,"title":"扩展过滤器作用域","slug":"扩展过滤器作用域","link":"#扩展过滤器作用域","children":[{"level":4,"title":"扩展过滤器响应","slug":"扩展过滤器响应","link":"#扩展过滤器响应","children":[]}]},{"level":3,"title":"扩展模型查询","slug":"扩展模型查询","link":"#扩展模型查询","children":[]},{"level":3,"title":"扩展记录集合","slug":"扩展记录集合","link":"#扩展记录集合","children":[]},{"level":3,"title":"自定义列类型","slug":"自定义列类型","link":"#自定义列类型","children":[]}]}],"relativePath":"3.x/zh-cn/extend/lists/list-controller.md","filePath":"3.x/zh-cn/extend/lists/list-controller.md"}'),u={name:"3.x/zh-cn/extend/lists/list-controller.md"};function k(d,s,g,h,m,f){const o=t("pre-heading"),c=t("post-heading");return i(),r("div",null,[p(o),s[0]||(s[0]=n("h1",null,"列表控制器",-1)),p(c),s[1]||(s[1]=e(`<p><code>Backend\\Behaviors\\ListController</code> 类是一个控制器行为，用于轻松地向页面添加记录列表。该行为提供可排序和可搜索的列表，记录上可选择性地添加链接。该行为提供控制器操作 <code>index</code>，但列表可以在任何地方渲染，并且可以使用多个列表定义。</p><p>列表行为依赖于列表<a href="./../../element/list-columns.html">列定义</a>和<a href="./../database/model.html">模型类</a>。要使用列表行为，您应该将其添加到控制器类的 <code>$implement</code> 属性中。同时，应定义 <code>$listConfig</code> 类属性，其值应引用用于配置行为属性的 YAML 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_list.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>通常列表和<a href="./../forms/form-controller.html">表单控制器</a>会在同一个控制器中一起使用。</p></div><h2 id="配置列表行为"><a href="#配置列表行为" class="header-anchor">#</a> 配置列表行为</h2><p>在 <code>$listConfig</code> 属性中引用的配置文件以 YAML 格式定义。该文件应放置在控制器的<a href="./../system/controllers.html">视图目录</a>中。以下是一个典型的列表行为配置文件示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">title</span><span class="token punctuation">:</span> Blog Posts
<span class="token key atrule">list</span><span class="token punctuation">:</span> ~/plugins/acme/blog/models/post/columns.yaml
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Blog\\Models\\Post
<span class="token key atrule">recordUrl</span><span class="token punctuation">:</span> acme/blog/posts/update/<span class="token punctuation">:</span>id
</code></pre></div><p>以下属性在列表配置文件中是必需的。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>此列表的标题。</td></tr><tr><td><strong>list</strong></td><td>配置数组或列表列定义文件的引用，参见<a href="./../../element/list-columns.html">列表列</a>。</td></tr><tr><td><strong>modelClass</strong></td><td>模型类名，列表数据从此模型加载。</td></tr></tbody></table></div><p>以下列出的配置属性是可选的。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>filter</strong></td><td>过滤器配置，参见<a href="./filters.html">列表过滤器</a>。</td></tr><tr><td><strong>recordUrl</strong></td><td>将每条列表记录链接到另一个页面。例如：<strong>users/update:id</strong>。<code>:id</code> 部分将被替换为记录标识符。这允许您将列表行为与<a href="./../forms/form-controller.html">表单行为</a>链接起来。</td></tr><tr><td><strong>recordOnClick</strong></td><td>点击记录时执行的自定义 JavaScript 代码。</td></tr><tr><td><strong>noRecordsMessage</strong></td><td>未找到记录时显示的消息，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>deleteMessage</strong></td><td>批量删除记录时显示的消息，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>noRecordsDeletedMessage</strong></td><td>触发批量删除操作但没有记录被删除时显示的消息，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>recordsPerPage</strong></td><td>每页显示的记录数，使用 0 表示不分页。默认值：<code>0</code></td></tr><tr><td><strong>perPageOptions</strong></td><td>每页项目数的选项。默认值：<code>[20, 40, 80, 100, 120]</code></td></tr><tr><td><strong>showPageNumbers</strong></td><td>分页时显示页码。禁用此项可在处理大型表时提高列表性能。默认值：<code>true</code></td></tr><tr><td><strong>toolbar</strong></td><td>工具栏小部件配置文件的引用，或包含配置的数组（见下文）。</td></tr><tr><td><strong>showSorting</strong></td><td>在每列上显示排序链接。默认值：<code>true</code></td></tr><tr><td><strong>defaultSort</strong></td><td>当用户未定义偏好时，设置默认排序列和方向。支持字符串或带有 <code>column</code> 和 <code>direction</code> 键的数组。方向可以是 <code>asc</code>（升序，默认）或 <code>desc</code>（降序）。</td></tr><tr><td><strong>showCheckboxes</strong></td><td>在每条记录旁边显示复选框。默认值：<code>false</code>。</td></tr><tr><td><strong>showSetup</strong></td><td>显示列表列设置按钮。默认值：<code>false</code>。</td></tr><tr><td><strong>structure</strong></td><td>启用结构化列表，详情请参阅<a href="./structures.html">记录排序文章</a>。</td></tr><tr><td><strong>customViewPath</strong></td><td>指定自定义视图路径以覆盖列表使用的局部视图，可选。</td></tr><tr><td><strong>customPageName</strong></td><td>指定在页面 URL 中用于分页记录的自定义变量名。设置为 <code>false</code> 可禁用在 URL 中存储页码。默认值：<code>page</code>。</td></tr></tbody></table></div><h3 id="添加工具栏"><a href="#添加工具栏" class="header-anchor">#</a> 添加工具栏</h3><p>要在列表中包含工具栏，请在列表配置 YAML 文件中添加以下配置：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">toolbar</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttons</span><span class="token punctuation">:</span> list_toolbar
    <span class="token key atrule">search</span><span class="token punctuation">:</span>
        <span class="token key atrule">prompt</span><span class="token punctuation">:</span> Find records
</code></pre></div><p>工具栏配置允许：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>buttons</strong></td><td>包含工具栏按钮的控制器局部视图文件引用。例如：<strong>_list_toolbar.htm</strong></td></tr><tr><td><strong>search</strong></td><td>搜索小部件配置文件的引用，或包含配置的数组。</td></tr></tbody></table></div><p>搜索配置支持以下属性：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>prompt</strong></td><td>没有活动搜索时显示的占位符，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>mode</strong></td><td>定义搜索策略，可包含所有词、任意词或精确短语。支持的选项：<code>all</code>、<code>any</code>、<code>exact</code>。默认值：<code>all</code>。</td></tr><tr><td><strong>scope</strong></td><td>指定在<strong>列表模型</strong>中定义的<a href="./../database/model.html">模型查询作用域</a>方法，应用于搜索查询。第一个参数将包含查询对象（与常规作用域方法相同），第二个参数将包含搜索词，第三个参数将是要搜索的列的数组。</td></tr><tr><td><strong>searchOnEnter</strong></td><td>将此设置为 true 将使搜索小部件等待按下 Enter 键后才开始搜索（默认行为是在有人在搜索字段中输入内容并暂停片刻后自动开始搜索）。默认值：<code>false</code>。</td></tr></tbody></table></div>`,18)),s[2]||(s[2]=n("p",null,[a("上面引用的工具栏按钮局部视图应包含带有一些按钮的工具栏控件定义。该局部视图也可以包含带有图表的"),n("a",{href:"https://octobercms.com/docs/ui/scoreboard",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("记分板控件"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a("。以下是一个工具栏局部视图的示例，其中 "),n("strong",null,"New Post"),a(" 按钮引用了"),n("a",{href:"./forms.html"},"表单行为"),a("提供的 "),n("strong",null,"create"),a(" 操作：")],-1)),s[3]||(s[3]=e(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>toolbar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts/create&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary oc-icon-plus<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        New Post
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>使用列表复选框时，您可以使用 <code>data-list-checked-trigger</code> 属性切换按钮的启用状态。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">&lt;</span>button
    type<span class="token operator">=</span><span class="token string double-quoted-string">&quot;button&quot;</span>
    <span class="token keyword">class</span><span class="token operator">=</span><span class="token string double-quoted-string">&quot;btn btn-primary&quot;</span>
    data<span class="token operator">-</span><span class="token keyword">list</span><span class="token operator">-</span>checked<span class="token operator">-</span>trigger<span class="token operator">&gt;</span>
    Delete Selected
<span class="token operator">&lt;</span><span class="token operator">/</span>button<span class="token operator">&gt;</span>
</code></pre></div><p>您也可以使用 <code>data-list-checked-request</code> 属性将选中的值传递给 AJAX 请求。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">&lt;</span>button
    type<span class="token operator">=</span><span class="token string double-quoted-string">&quot;button&quot;</span>
    <span class="token keyword">class</span><span class="token operator">=</span><span class="token string double-quoted-string">&quot;btn btn-primary&quot;</span>
    data<span class="token operator">-</span>request<span class="token operator">=</span><span class="token string double-quoted-string">&quot;onDelete&quot;</span>
    data<span class="token operator">-</span><span class="token keyword">list</span><span class="token operator">-</span>checked<span class="token operator">-</span>request<span class="token operator">&gt;</span>
    Delete Selected
<span class="token operator">&lt;</span><span class="token operator">/</span>button<span class="token operator">&gt;</span>
</code></pre></div><h3 id="过滤列表"><a href="#过滤列表" class="header-anchor">#</a> 过滤列表</h3><p>要通过用户定义的输入过滤列表，请在 YAML 文件中添加以下列表配置：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">filter</span><span class="token punctuation">:</span> $/acme/blog/models/post/scopes.yaml
</code></pre></div><p><strong>filter</strong> 属性应引用<a href="./filters.html">过滤器配置文件</a>路径或提供包含配置的数组。</p><h2 id="定义列表列"><a href="#定义列表列" class="header-anchor">#</a> 定义列表列</h2><div class="custom-block aside"><p>可用的列表列属性可在<a href="./../../element/list-columns.html">列表列定义</a>页面找到。</p></div><p>列表列通过 YAML 文件定义。列配置被列表行为用于创建记录表和在表格单元格中显示模型列。该文件放置在插件 <strong>models</strong> 目录的子目录中。子目录名称与小写的模型类名匹配。文件名没有限制，但 <strong>columns.yaml</strong> 和 <strong>list_columns.yaml</strong> 是常用名称。列表列文件位置示例：</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           └── <code>models</code>
|               ├── post  <em>← 配置目录</em>
|               |   └── columns.yaml  <em>← 配置文件</em>
|               └── Post.php  <em>← 模型类</em></p>
</code></pre><p>以下示例展示了列表列定义文件的典型内容。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># columns.yaml</span>
<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Name
    <span class="token key atrule">email</span><span class="token punctuation">:</span> Email
</code></pre></div><h2 id="显示列表"><a href="#显示列表" class="header-anchor">#</a> 显示列表</h2><p>通常列表在<a href="./../system/views.html">索引视图</a>文件中显示。由于列表包含工具栏，视图文件将仅包含单个 <code>listRender</code> 方法调用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="多个列表定义"><a href="#多个列表定义" class="header-anchor">#</a> 多个列表定义</h2><p>列表行为可以使用命名定义在同一控制器中支持多个列表。<code>$listConfig</code> 属性可以定义为数组，其中键是定义名称，值是配置文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;templates&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_templates_list.yaml&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;layouts&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_layouts_list.yaml&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>然后可以通过在调用 <code>listRender</code> 方法时将定义名称作为第一个参数传递来显示每个定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;templates&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="扩展列表行为"><a href="#扩展列表行为" class="header-anchor">#</a> 扩展列表行为</h2><p>有时您可能希望修改默认的列表行为，有几种方式可以实现。</p><h3 id="扩展列表配置"><a href="#扩展列表配置" class="header-anchor">#</a> 扩展列表配置</h3><p>您可以使用 <code>listGetConfig</code> 方法动态扩展列表配置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listGetConfig</span><span class="token punctuation">(</span><span class="token variable">$definition</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$config</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ListController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">listGetConfig</span><span class="token punctuation">(</span><span class="token variable">$definition</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Implement structure dynamically</span>
    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">structure</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;showTree&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$config</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖控制器操作"><a href="#覆盖控制器操作" class="header-anchor">#</a> 覆盖控制器操作</h3><p>您可以在控制器中使用自己的逻辑来实现 <code>index</code> 操作方法，然后可选地调用列表行为的 <code>index</code> 父方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">//</span>
    <span class="token comment">// Do any custom code here</span>
    <span class="token comment">//</span>

    <span class="token comment">// Call the ListController behavior index() method</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ListController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖视图"><a href="#覆盖视图" class="header-anchor">#</a> 覆盖视图</h3><p><code>ListController</code> 行为有一个主容器视图，您可以通过在控制器目录中创建名为 <code>_list_container.php</code> 的特殊文件来覆盖它。以下示例将向列表添加侧边栏：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$toolbar</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$toolbar</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>row row-flush<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-sm-3<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        [Insert sidebar here]
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-sm-9 list-with-sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>该行为将调用一个 <code>Lists</code> 小部件，该小部件还包含许多您可以覆盖的视图。这可以通过指定列表配置选项中描述的 <code>customViewPath</code> 属性来实现。小部件将首先在此路径中查找视图，然后回退到默认位置。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># Custom view path</span>
<span class="token key atrule">customViewPath</span><span class="token punctuation">:</span> $/acme/blog/controllers/reviews/list
</code></pre></div><div class="custom-block tip"><p>使用子目录（例如名为 <code>list</code>）以避免冲突是一个好做法。</p></div><p>例如，要修改列表主体行标记，请在控制器目录中创建名为 <code>list/_list_body_row.php</code> 的文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>tr</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$columns</span> <span class="token keyword">as</span> <span class="token variable">$key</span> <span class="token operator">=&gt;</span> <span class="token variable">$column</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>td</span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getColumnValue</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$column</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>td</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endforeach</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>tr</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="扩展列定义"><a href="#扩展列定义" class="header-anchor">#</a> 扩展列定义</h3><p>您可以通过绑定 <code>backend.list.extendColumns</code> <a href="./../services/event.html">全局事件</a>从外部扩展另一个控制器的列。事件函数将接收一个 <code>$list</code> 参数，代表 <code>Backend\\Widgets\\Lists</code> 对象，您可以使用 <code>getController</code> 和 <code>getModel</code> 方法来检查执行上下文。</p><p>由于此事件可能影响所有列表，因此必须检查控制器和模型是否为正确的类型。以下是使用 <code>addColumns</code> 方法向事件日志列表添加新列并修改现有列的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$list</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>EventLogs</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EventLog</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add a new column</span>
    <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_column&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Column&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Modify an existing column</span>
    <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">useConfig</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;path&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;column_title&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以通过在控制器类中覆盖 <code>listExtendColumns</code> 方法来内部扩展列表列。这只会影响 <code>ListController</code> 行为使用的列表。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendColumns</span><span class="token punctuation">(</span><span class="token variable">$list</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getColumn</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>以下方法在 <code>$list</code> 对象上可用。</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>addColumns</strong></td><td>向列表添加新列</td></tr><tr><td><strong>removeColumn</strong></td><td>从列表移除列</td></tr><tr><td><strong>getColumn</strong></td><td>返回现有列定义</td></tr></tbody></table></div><p>每个方法接受类似于<a href="./../../element/list-columns.html">列表列配置</a>的列数组。</p><h3 id="注入-css-行类"><a href="#注入-css-行类" class="header-anchor">#</a> 注入 CSS 行类</h3><p>您可以通过在控制器类上添加 <code>listInjectRowClass</code> 方法来注入自定义 CSS 行类。此方法可接受两个参数，<strong>$record</strong> 代表单个模型记录，<strong>$definition</strong> 包含列表小部件定义的名称。您可以返回包含行类的任何字符串值。这些类将被添加到行的 HTML 标记中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Lessons</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listInjectRowClass</span><span class="token punctuation">(</span><span class="token variable">$lesson</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// Strike through past lessons</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$lesson</span><span class="token operator">-&gt;</span><span class="token property">lesson_date</span><span class="token operator">-&gt;</span><span class="token function">lt</span><span class="token punctuation">(</span><span class="token class-name static-context">Carbon</span><span class="token operator">::</span><span class="token function">today</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;strike&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>有一个特殊的 CSS 类 <code>nolink</code>，即使列表小部件定义了 <code>recordUrl</code> 或 <code>recordOnClick</code> 属性，也可强制行不可点击。在事件中返回此类将允许您使记录不可点击——例如，用于软删除的行或信息行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listInjectRowClass</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;nolink&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖列-url"><a href="#覆盖列-url" class="header-anchor">#</a> 覆盖列 URL</h3><p>您可以通过覆盖 <code>listOverrideRecordUrl</code> 方法来指定列记录的点击操作。此方法可以返回一个字符串作为新的后台 URL 或一个包含复杂定义的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;acme/test/services/preview/<span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">}</span></span>&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>要覆盖 onclick 行为，返回一个带有 <code>onclick</code> 键的数组，并将 <code>url</code> 设置为 null。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_banned</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;onclick&#39;</span> <span class="token operator">=&gt;</span> <span class="token string double-quoted-string">&quot;alert(&#39;Unable to click&#39;)&quot;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant">null</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>要使列完全不可点击，返回一个将 <code>clickable</code> 键设置为 false 的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_disabled</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;clickable&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展过滤器作用域"><a href="#扩展过滤器作用域" class="header-anchor">#</a> 扩展过滤器作用域</h3><p>您可以通过绑定 <code>backend.filter.extendScopes</code> <a href="./../services/event.html">全局事件</a>来扩展另一个控制器的过滤器作用域。此方法可接受参数 <code>$filter</code>，代表 <code>Backend\\Widgets\\Filter</code> 对象，您可以使用 <code>getController</code>、<code>getModel</code> 和 <code>getContext</code> 方法来检查执行上下文。</p><p>由于此事件可能影响所有过滤器，因此必须检查控制器和模型是否为正确的类型。以下是使用 <code>addScopes</code> 方法向事件日志列表添加新字段并调整 CSS 类的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.filter.extendScopes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>EventLogs</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EventLog</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add a new scope</span>
    <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">addScopes</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Filter Scope&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Add custom CSS classes to the filter widget</span>
    <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token property">cssClasses</span> <span class="token operator">=</span> <span class="token function">array_merge</span><span class="token punctuation">(</span>
        <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token property">cssClasses</span><span class="token punctuation">,</span>
        <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;my-array&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;of-classes&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以在控制器类内部扩展过滤器作用域，只需覆盖 <code>listFilterExtendScopes</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listFilterExtendScopes</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">addScopes</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>以下方法在 <code>$filter</code> 对象上可用。可用的作用域与<a href="./filters.html">列表过滤器配置</a>相同。</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>addScopes</strong></td><td>使用<a href="./filters.html">列表过滤器配置</a>向过滤器小部件添加新作用域</td></tr><tr><td><strong>removeScope</strong></td><td>从过滤器小部件移除作用域</td></tr><tr><td><strong>getScope</strong></td><td>返回现有作用域定义</td></tr></tbody></table></div><h4 id="扩展过滤器响应"><a href="#扩展过滤器响应" class="header-anchor">#</a> 扩展过滤器响应</h4><p><code>listExtendRefreshResults</code> 方法可以在列表更新时与 AJAX 更新响应交互，并应返回额外的局部视图更新数组。<code>listGetFilterWidget</code> 将返回过滤器小部件以访问作用域。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">,</span> <span class="token variable">$result</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listGetFilterWidget</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getScope</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status_code&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#my-partial-id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展模型查询"><a href="#扩展模型查询" class="header-anchor">#</a> 扩展模型查询</h3><p>可以通过在控制器类中覆盖 <code>listExtendQuery</code> 方法来扩展列表<a href="./../database/model.html">数据库模型</a>的查询。此示例将确保软删除的记录包含在列表数据中，方法是对查询应用 <strong>withTrashed</strong> 作用域。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在同一控制器中处理多个列表定义时，您可以使用 <code>listExtendQuery</code> 的第二个参数，该参数包含定义的名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;inbox&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_inbox_list.yaml&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;trashed&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_trashed_list.yaml&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$definition</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$definition</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;trashed&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以连接其他表以辅助搜索和排序。以下示例将连接 <code>post_statuses</code> 表并将 <code>status_sort_order</code> 和 <code>status_name</code> 列引入查询。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_statuses&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts.status_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;post_statuses.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">addSelect</span><span class="token punctuation">(</span>
        <span class="token string single-quoted-string">&#39;post_statuses.sort_order as status_sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;post_statuses.name as status_name&#39;</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>也可以通过覆盖 <code>listFilterExtendQuery</code> 方法来扩展<a href="./filters.html">列表过滤器</a>模型查询。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listFilterExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeName</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;all&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展记录集合"><a href="#扩展记录集合" class="header-anchor">#</a> 扩展记录集合</h3><p>可以通过在控制器类中覆盖 <code>listExtendRecords</code> 方法来扩展列表使用的记录集合。此示例使用<a href="./../database/collection.html">记录集合</a>上的 <code>sort</code> 方法来更改记录的排序顺序。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendRecords</span><span class="token punctuation">(</span><span class="token variable">$records</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$a</span><span class="token punctuation">,</span> <span class="token variable">$b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$a</span><span class="token operator">-&gt;</span><span class="token function">computedVal</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token variable">$b</span><span class="token operator">-&gt;</span><span class="token function">computedVal</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="自定义列类型"><a href="#自定义列类型" class="header-anchor">#</a> 自定义列类型</h3><p>自定义列表列类型可以通过<a href="./../extending.html">插件注册文件</a>的 <code>registerListColumnTypes</code> 方法在后台注册。该方法应返回一个数组，其中键是类型名称，值是可调用函数。可调用函数接收三个参数：原生的 <code>$value</code>、<code>$column</code> 定义对象和模型 <code>$record</code> 对象。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerListColumnTypes</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// A local method, i.e $this-&gt;evalUppercaseListColumn()</span>
        <span class="token string single-quoted-string">&#39;uppercase&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;evalUppercaseListColumn&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

        <span class="token comment">// Using an inline closure</span>
        <span class="token string single-quoted-string">&#39;loveit&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I love <span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$value</span><span class="token punctuation">}</span></span>&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">evalUppercaseListColumn</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$column</span><span class="token punctuation">,</span> <span class="token variable">$record</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>使用自定义列表列类型就像使用 <code>type</code> 属性按名称调用它一样简单。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># columns.yaml</span>
<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">secret_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Secret code
        <span class="token key atrule">type</span><span class="token punctuation">:</span> uppercase
</code></pre></div>`,88))])}const b=l(u,[["render",k]]);export{y as __pageData,b as default};
